batch := reader.ReadBatch(ctx)        // one partition, offsets in order
defer batch.Close()
for {
    m, err := batch.ReadMessage()
    if err != nil {
        break
    }
    g := groups.add(m.Headers, m.Offset)   // sequence id from headers
    if g.complete() {
        deliver(g); groups.release(g.id)
    }
}
